// Writes api/_lib/sites.gen.ts: what the server needs to know about every site in this one
// deployment (one folder in clients/ = one couple = one address, /<slug>/). Run by `npm run build`;
// the generated file is committed too, so the functions always have it.
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';

const sites = {};
for (const slug of readdirSync('clients').sort()) {
  if (slug.startsWith('_') || !existsSync(`clients/${slug}/profile.json`)) continue;
  if (!/^[a-z0-9][a-z0-9-]{1,40}$/.test(slug) || slug === 'api') throw new Error(`clients/${slug}: the folder name is the address, use a-z, 0-9 and -`);
  const p = JSON.parse(readFileSync(`clients/${slug}/profile.json`, 'utf8'));
  if (p.slug !== slug) throw new Error(`clients/${slug}/profile.json: "slug" must be "${slug}"`);
  const who = (role) => ({ name: p[role].name, gender: p[role].gender, login: [p[role].name, ...(p.login?.[role] ?? [])] });
  sites[slug] = { title: p.title, admin: who('admin'), partner: who('partner'), timeZone: p.timeZone ?? 'Asia/Jerusalem', demo: !!p.demo };
}
const out = `// Generated by scripts/gen-sites.mjs from clients/*/profile.json. Do not edit.
export interface SitePerson { name: string; gender: 'm' | 'f'; login: string[] }
export interface SiteInfo { title: string; admin: SitePerson; partner: SitePerson; timeZone: string; demo: boolean }
export const SITES: Record<string, SiteInfo> = ${JSON.stringify(sites, null, 2)};
`;
writeFileSync('api/_lib/sites.gen.ts', out);
console.log('sites:', Object.keys(sites).join(', '));
